#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you wrote.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

banner "dsh local service setup"

DSH_ENV="$HOME/.dsh/.env"
DSH_HOME="$HOME/.local/share/im-bridge/dsh"
DSH_SUPERVISOR="$DSH_HOME/supervisor.mjs"
# The runtime is a private pnpm project, never a global install. dsh 0.1.1-rc.2
# declares only 2 of the client-ui plugins it imports at boot, so the runtime
# pins node-linker=hoisted; pnpm's default isolated layout fails with
# ERR_MODULE_NOT_FOUND. staging sits beside runtime so the swap is a
# same-filesystem rename.
DSH_RUNTIME="$DSH_HOME/runtime"
DSH_STAGING="$DSH_HOME/staging"
DSH_FILES_STAGING="$DSH_HOME/staging-files"
DSH_PREVIOUS_RUNTIME="$DSH_HOME/runtime.previous"
DSH_RUNTIME_BIN="$DSH_RUNTIME/node_modules/.bin/dsh"
DSH_AGENTS_HOME="$HOME/.dsh/empty-agents"
LOG_DIR="$HOME/Library/Logs/im-bridge"
LOG_FILE="$LOG_DIR/dsh.log"
PLIST="$HOME/Library/LaunchAgents/dev.im-bridge.dsh.plist"
LABEL="dev.im-bridge.dsh"
DOMAIN="gui/$(id -u)"
BACKUP_DIR=""
SERVICE_WAS_LOADED=0
SERVICE_STOPPED=0
FILES_REPLACED=0
OLD_RUNTIME_MOVED=0
NEW_RUNTIME_INSTALLED=0
TRANSACTION_STARTED=0

rollback() {
  local status=$?
  (( status == 0 || TRANSACTION_STARTED == 0 )) && return 0
  if (( SERVICE_STOPPED == 1 )); then
    launchctl bootout "$DOMAIN/$LABEL" >/dev/null 2>&1 || true
  fi
  if (( NEW_RUNTIME_INSTALLED == 1 )); then
    rm -rf "$DSH_RUNTIME"
  fi
  if (( OLD_RUNTIME_MOVED == 1 )); then
    mv "$DSH_PREVIOUS_RUNTIME" "$DSH_RUNTIME"
  fi
  if (( FILES_REPLACED == 1 )); then
    if [[ -n "$BACKUP_DIR" && -f "$BACKUP_DIR/supervisor.mjs" ]]; then
      cp "$BACKUP_DIR/supervisor.mjs" "$DSH_SUPERVISOR"
    else
      rm -f "$DSH_SUPERVISOR"
    fi
    if [[ -n "$BACKUP_DIR" && -f "$BACKUP_DIR/dsh.plist" ]]; then
      cp "$BACKUP_DIR/dsh.plist" "$PLIST"
    else
      rm -f "$PLIST"
    fi
  fi
  if (( SERVICE_STOPPED == 1 && SERVICE_WAS_LOADED == 1 )) && [[ -f "$PLIST" ]]; then
    launchctl bootstrap "$DOMAIN" "$PLIST" || warn "failed to restore the previous LaunchAgent; run setup again"
  fi
  # Staged files this run created but never moved into place.
  [[ -z "${SUPERVISOR_RESERVED:-}" ]] || rm -f "$SUPERVISOR_RESERVED"
  [[ -z "${SUPERVISOR_TMP:-}" ]] || rm -f "$SUPERVISOR_TMP"
  [[ -z "${PLIST_TMP:-}" ]] || rm -f "$PLIST_TMP"
  rm -rf "$DSH_STAGING" "$DSH_FILES_STAGING"
  [[ -z "$BACKUP_DIR" ]] || rm -rf "$BACKUP_DIR"
  # The dsh log survives rollback on purpose: it is the only record of why a
  # start attempt failed, and the supervisor never writes the key into it.
  warn "setup failed; previous runtime, files, and service were restored when available"
  [[ ! -f "$LOG_FILE" ]] || note "dsh log kept for diagnosis: $LOG_FILE"
}
trap rollback EXIT

stage "Pre-flight checks"
say "This verifies local requirements without reading or printing your API key."
[[ "$(uname -s)" == "Darwin" ]] || { warn "this wizard requires macOS"; exit 1; }
[[ -t 0 ]] || { warn "run this wizard from an interactive terminal"; exit 1; }
for command in node npm pnpm launchctl lsof curl plutil; do
  command -v "$command" >/dev/null 2>&1 || { warn "$command is missing"; exit 1; }
done
NODE_BIN=$(command -v node)
NODE_DIR=$(dirname "$NODE_BIN")
NODE_MAJOR=$("$NODE_BIN" -p 'Number(process.versions.node.split(".")[0])')
(( NODE_MAJOR >= 24 )) || { warn "Node.js 24 or newer is required"; exit 1; }
# The hoisted-runtime layout is measured against this exact pnpm release.
[[ "$(pnpm --version)" == "11.21.0" ]] || { warn "pnpm 11.21.0 is required by this repository"; exit 1; }
[[ -f "$DSH_ENV" ]] || { warn "$DSH_ENV does not exist"; exit 1; }
[[ "$(stat -f '%Lp' "$DSH_ENV")" == "600" ]] || { warn "$DSH_ENV must have mode 600"; exit 1; }
awk '
  /^[[:space:]]*(#|$)/ { next }
  /^DEEPSEEK_API_KEY=[^[:space:]]+$/ { valid += 1; next }
  { invalid += 1 }
  END { exit !(valid == 1 && invalid == 0) }
' "$DSH_ENV" || {
  warn "$DSH_ENV must contain one non-empty DEEPSEEK_API_KEY plus comments and blank lines"
  exit 1
}
if launchctl print "$DOMAIN/$LABEL" >/dev/null 2>&1; then
  SERVICE_WAS_LOADED=1
fi
if LISTENER_PID=$(lsof -nP -t -a -iTCP@127.0.0.1:3080 -sTCP:LISTEN 2>/dev/null | head -n1) && [[ -n "$LISTENER_PID" ]]; then
  SERVICE_PID=$(launchctl print "$DOMAIN/$LABEL" 2>/dev/null | awk '/^[[:space:]]*pid = / { print $3; exit }')
  PARENT_PID=$(ps -o ppid= -p "$LISTENER_PID" | tr -d ' ')
  if [[ -n "$SERVICE_PID" && "$SERVICE_PID" == "$PARENT_PID" ]]; then
    note "The existing $LABEL child owns port 3080 and will be replaced."
  else
    warn "TCP port 3080 is used by a process outside $LABEL"
    exit 1
  fi
fi
note "Node $("$NODE_BIN" --version), pnpm $(pnpm --version), credential file mode 600."
pause "Pre-flight checks passed. Press Enter to continue."

stage "Select dsh version"
say "The registry candidate is shown now; installation occurs after local files validate."
DSH_VERSION=$(npm view @deepseek-ai/dsh version)
[[ "$DSH_VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+([+-][0-9A-Za-z.-]+)?$ ]] || {
  warn "npm returned an invalid version: $DSH_VERSION"
  exit 1
}
note "Candidate: @deepseek-ai/dsh@$DSH_VERSION"
[[ "$DSH_VERSION" != *-* ]] || warn "This candidate is a prerelease."
confirm "Use this exact version for the service?" || exit 1
note "Selected @deepseek-ai/dsh@$DSH_VERSION."
pause "Version selected. Press Enter to continue."

stage "Create service files"
say "A single supervisor strictly parses credentials, owns logging, and propagates dsh failures."
mkdir -p "$DSH_HOME" "$DSH_AGENTS_HOME" "$LOG_DIR" "$HOME/Library/LaunchAgents"
chmod 700 "$DSH_HOME" "$DSH_AGENTS_HOME"
rm -rf "$DSH_FILES_STAGING"
mkdir -m 700 "$DSH_FILES_STAGING"
TRANSACTION_STARTED=1
# Node 24 selects the module loader from the final extension, so the temp file
# must still end in .mjs or --check fails with ERR_UNKNOWN_FILE_EXTENSION. BSD
# mktemp only expands XXXXXX at the end of a template, so claim the name
# exclusively first, then move it back under the .mjs extension.
SUPERVISOR_RESERVED=$(mktemp "$DSH_FILES_STAGING/supervisor.XXXXXX")
SUPERVISOR_TMP="${SUPERVISOR_RESERVED}.mjs"
mv "$SUPERVISOR_RESERVED" "$SUPERVISOR_TMP"
cat > "$SUPERVISOR_TMP" <<EOF
import {
  closeSync,
  existsSync,
  openSync,
  readFileSync,
  readdirSync,
  renameSync,
  rmSync,
  statSync,
  writeSync,
} from "node:fs";
import { basename, dirname } from "node:path";
import { spawn } from "node:child_process";

const envFile = "$DSH_ENV";
const envMode = statSync(envFile).mode & 0o777;
if (envMode !== 0o600) throw new Error("dsh env must have mode 600");
const logFile = "$LOG_FILE";
const maxBytes = 10485760;
const fileCount = 5;
const lines = readFileSync(envFile, "utf8")
  .split(/\r?\n/)
  .filter(line => !/^\s*(#|$)/.test(line));
if (lines.length !== 1) throw new Error("dsh env must contain only DEEPSEEK_API_KEY");
const match = /^DEEPSEEK_API_KEY=([^\s]+)$/.exec(lines[0]);
if (!match) throw new Error("invalid or empty DEEPSEEK_API_KEY");
if (process.env.DSH_SUPERVISOR_VALIDATE === "1") process.exit(0);

let fd;
let size;
function openLog() {
  fd = openSync(logFile, "a", 0o600);
  size = statSync(logFile).size;
}
function rotate() {
  closeSync(fd);
  rmSync(logFile + "." + (fileCount - 1), { force: true });
  for (let n = fileCount - 2; n >= 1; n -= 1) {
    if (existsSync(logFile + "." + n)) renameSync(logFile + "." + n, logFile + "." + (n + 1));
  }
  if (existsSync(logFile)) renameSync(logFile, logFile + ".1");
  openLog();
}
function writeChunk(chunk) {
  let offset = 0;
  while (offset < chunk.length) {
    if (size >= maxBytes) rotate();
    const length = Math.min(maxBytes - size, chunk.length - offset);
    writeSync(fd, chunk, offset, length);
    size += length;
    offset += length;
  }
}
if (existsSync(logFile) && statSync(logFile).size > maxBytes) {
  const oldContent = readFileSync(logFile);
  rmSync(logFile);
  openLog();
  writeChunk(oldContent);
} else {
  openLog();
}
for (const name of readdirSync(dirname(logFile))) {
  const prefix = basename(logFile) + ".";
  if (!name.startsWith(prefix)) continue;
  const number = Number(name.slice(prefix.length));
  if (Number.isInteger(number) && number >= fileCount) rmSync(dirname(logFile) + "/" + name);
}
for (let n = 1; n < fileCount; n += 1) {
  const archive = logFile + "." + n;
  if (existsSync(archive) && statSync(archive).size > maxBytes) {
    const content = readFileSync(archive);
    const archiveFd = openSync(archive, "w", 0o600);
    writeSync(archiveFd, content.subarray(content.length - maxBytes));
    closeSync(archiveFd);
  }
}

const child = spawn("$DSH_RUNTIME_BIN", ["web", "--no-open", "--port", "3080"], {
  cwd: "$HOME",
  env: {
    ...process.env,
    PATH: "$NODE_DIR:/usr/bin:/bin:/usr/sbin:/sbin",
    DEEPSEEK_API_KEY: match[1],
    DSH_AGENTS_HOME: "$DSH_AGENTS_HOME",
  },
  stdio: ["ignore", "pipe", "pipe"],
});
child.stdout.on("data", writeChunk);
child.stderr.on("data", writeChunk);
let stopping = false;
for (const signal of ["SIGTERM", "SIGINT"]) {
  process.on(signal, () => {
    stopping = true;
    child.kill(signal);
  });
}
child.on("error", error => {
  writeChunk(Buffer.from("dsh spawn failed: " + error.message + "\\n"));
  closeSync(fd);
  process.exit(1);
});
child.on("exit", code => {
  closeSync(fd);
  process.exit(stopping ? 0 : (code ?? 1));
});
EOF
chmod 700 "$SUPERVISOR_TMP"
"$NODE_BIN" --check "$SUPERVISOR_TMP"
DSH_SUPERVISOR_VALIDATE=1 "$NODE_BIN" "$SUPERVISOR_TMP"

PLIST_TMP="$DSH_FILES_STAGING/dsh.plist"
cat > "$PLIST_TMP" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>$LABEL</string>
  <key>ProgramArguments</key>
  <array>
    <string>$NODE_BIN</string>
    <string>$DSH_SUPERVISOR</string>
  </array>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <dict>
    <key>SuccessfulExit</key>
    <false/>
  </dict>
  <key>ThrottleInterval</key>
  <integer>10</integer>
</dict>
</plist>
EOF
chmod 600 "$PLIST_TMP"
plutil -lint "$PLIST_TMP" >/dev/null
note "Created credential-safe staged service files with bounded 10 MB x 5 logs."
pause "Service files validated. Press Enter to install dsh."

stage "Install pinned dsh runtime"
say "pnpm installs the exact version into a staging directory; the running service keeps serving until it verifies."
note "This downloads about 450 packages and takes roughly 3 minutes on a cold store."
rm -rf "$DSH_STAGING"
mkdir -m 700 "$DSH_STAGING"
printf '{"private":true}\n' > "$DSH_STAGING/package.json"
# node-linker=hoisted is load-bearing: dsh imports client-ui plugins it never
# declares, and only a hoisted node_modules puts them where its loader looks.
printf 'node-linker=hoisted\n' > "$DSH_STAGING/.npmrc"
# Keep the runtime self-contained as a single-package pnpm workspace.
printf 'packages:\n  - "."\n' > "$DSH_STAGING/pnpm-workspace.yaml"
# --ignore-scripts keeps install-time lifecycle scripts out of the deployment.
# Measured 2026-08-24 on macOS arm64: the published tarballs already carry the
# prebuilt native artefacts this platform needs. Global installs are excluded:
# they put the same tree behind a shared prefix this wizard must not own.
( cd "$DSH_STAGING" && pnpm add -w --ignore-scripts "@deepseek-ai/dsh@$DSH_VERSION" )
STAGED_BIN="$DSH_STAGING/node_modules/.bin/dsh"
[[ -x "$STAGED_BIN" ]] || { warn "dsh executable was not installed at $STAGED_BIN"; exit 1; }
INSTALLED_VERSION=$("$NODE_BIN" -p "require('$DSH_STAGING/node_modules/@deepseek-ai/dsh/package.json').version")
[[ "$INSTALLED_VERSION" == "$DSH_VERSION" ]] || { warn "installed version mismatch"; exit 1; }
# Swap runtime and service files only after every staged artifact validates.
# The old running process remains untouched throughout the long pnpm install.
BACKUP_DIR=$(mktemp -d)
[[ ! -f "$DSH_SUPERVISOR" ]] || cp "$DSH_SUPERVISOR" "$BACKUP_DIR/supervisor.mjs"
[[ ! -f "$PLIST" ]] || cp "$PLIST" "$BACKUP_DIR/dsh.plist"
rm -rf "$DSH_PREVIOUS_RUNTIME"
if [[ -d "$DSH_RUNTIME" ]]; then
  mv "$DSH_RUNTIME" "$DSH_PREVIOUS_RUNTIME"
  OLD_RUNTIME_MOVED=1
fi
mv "$DSH_STAGING" "$DSH_RUNTIME"
NEW_RUNTIME_INSTALLED=1
[[ -x "$DSH_RUNTIME_BIN" ]] || { warn "dsh executable is missing at $DSH_RUNTIME_BIN"; exit 1; }
FILES_REPLACED=1
mv "$SUPERVISOR_TMP" "$DSH_SUPERVISOR"
mv "$PLIST_TMP" "$PLIST"
rmdir "$DSH_FILES_STAGING"
note "Installed @deepseek-ai/dsh@$INSTALLED_VERSION into $DSH_RUNTIME."
pause "Installation verified. Press Enter to load the service."

stage "Start and verify dsh"
say "This replaces the loaded copy and verifies the supervisor child and HTTP response."
launchctl bootout "$DOMAIN/$LABEL" >/dev/null 2>&1 || true
SERVICE_STOPPED=1
launchctl bootstrap "$DOMAIN" "$PLIST"
launchctl kickstart -k "$DOMAIN/$LABEL"
for _ in {1..30}; do
  SERVICE_PID=$(launchctl print "$DOMAIN/$LABEL" 2>/dev/null | awk '/^[[:space:]]*pid = / { print $3; exit }')
  LISTENER_PID=$(lsof -nP -t -a -iTCP@127.0.0.1:3080 -sTCP:LISTEN 2>/dev/null | head -n1 || true)
  PARENT_PID=$([[ -n "$LISTENER_PID" ]] && ps -o ppid= -p "$LISTENER_PID" | tr -d ' ' || true)
  [[ -n "$SERVICE_PID" && "$SERVICE_PID" == "$PARENT_PID" ]] && break
  sleep 1
done
# The key never reaches the log, but a tail is still shown through a redactor
# and only for lines that match known-safe diagnostic shapes. Anything else is
# left in the file rather than printed.
show_log_tail() {
  [[ -f "$LOG_FILE" ]] || { warn "no dsh log exists at $LOG_FILE"; return 0; }
  if grep -q 'ERR_MODULE_NOT_FOUND' "$LOG_FILE"; then
    note "diagnosis: dsh reported a missing module"
  elif grep -q 'EADDRINUSE' "$LOG_FILE"; then
    note "diagnosis: dsh reported port 3080 in use"
  elif grep -q '^dsh web: http://127\.0\.0\.1:3080$' "$LOG_FILE"; then
    note "diagnosis: dsh reported that the web service started"
  else
    note "diagnosis: no recognized startup signature"
  fi
  note "full dsh log kept at $LOG_FILE"
}
[[ -n "${SERVICE_PID:-}" && "$SERVICE_PID" == "${PARENT_PID:-}" ]] || {
  warn "the LaunchAgent child did not become the port 3080 listener"
  show_log_tail
  exit 1
}
curl --fail --silent --show-error --max-time 5 "http://127.0.0.1:3080/" >/dev/null || {
  warn "dsh did not answer the root HTTP check"
  show_log_tail
  exit 1
}
FILES_REPLACED=0
OLD_RUNTIME_MOVED=0
NEW_RUNTIME_INSTALLED=0
SERVICE_STOPPED=0
